//! [`LlmOps`] for the autodiff decorator: each op runs the inner backend's
//! implementation (so CubeCL still uses the kernels in `kernels/`) and
//! records an analytic backward pass.
//!
//! Packed weights are frozen: `data`, `scales` and `biases` receive no
//! gradient, which is the QLoRA contract — the base stays quantized and only
//! adapters train (`qlora.rs`). The inputs `x` and, for RMS norm, `gamma` do.
//!
//! Callers: the `Dispatch` routing generated by `#[backend_extension]` in
//! `ops.rs` (the `Autodiff` arm). Calls: the inner backend's `LlmOps`,
//! including [`LlmOps::dequantize_packed`] for `Wᵀ` in the matmul backward passes.
//! Siblings: `fusion.rs` (the other decorator), and cortex-core's
//! `module::QLora`, which trains over a dense dequantized weight instead.

use cortex_core::backend::{
    Backend, TensorMetadata,
    autodiff::{
        Autodiff,
        checkpoint::{base::Checkpointer, strategy::CheckpointStrategy},
        grads::Gradients,
        ops::{Backward, Ops, OpsKind},
    },
    tensor::{FloatTensor, IntTensor},
};
use cortex_core::tensor::Shape;
use cortex_std::FloatDType;

use crate::LlmOps;
use crate::ops::decode_batched;

/// `dy · Wᵀ` for a packed `W[k, n]`, in the dtype of `dy`.
fn packed_input_grad<B: LlmOps>(
    grad: FloatTensor<B>,
    data: IntTensor<B>,
    scales: FloatTensor<B>,
    biases: FloatTensor<B>,
    format: (u32, usize, bool),
) -> FloatTensor<B> {
    let (bits, group_size, affine) = format;
    let dtype = FloatDType::from(grad.dtype());
    let w = B::float_cast(B::dequantize_packed(data, scales, biases, bits, group_size, affine), dtype);
    B::float_matmul(grad, B::float_transpose(w))
}

/// Gradients of `y = x · r · w` with `r = 1 / sqrt(mean(x²) + eps)` over the
/// last dimension and `w = gamma (+ 1)`:
///
/// - `dx = r · (dy·w) − x · r³ · mean((dy·w) · x)`
/// - `dgamma = Σ_rows dy · x · r`
///
/// Computed in f32 and returned in the dtypes of `x` and `gamma`.
pub(crate) fn rms_norm_backward<B: Backend>(
    x: FloatTensor<B>,
    gamma: FloatTensor<B>,
    grad: FloatTensor<B>,
    eps: f32,
    unit_offset: bool,
) -> (FloatTensor<B>, FloatTensor<B>) {
    let (x_dtype, g_dtype) = (FloatDType::from(x.dtype()), FloatDType::from(gamma.dtype()));
    let shape = x.shape();
    let rank = shape.num_dims();
    let d = shape[rank - 1];
    let x = B::float_cast(x, FloatDType::F32);
    let dy = B::float_cast(grad, FloatDType::F32);

    let ms = B::float_mean_dim(B::float_mul(x.clone(), x.clone()), rank - 1);
    let r = B::float_recip(B::float_sqrt(B::float_add_scalar(ms, eps.into())));

    let mut w_shape = alloc::vec![1usize; rank];
    w_shape[rank - 1] = d;
    let mut w = B::float_cast(gamma, FloatDType::F32);
    if unit_offset {
        w = B::float_add_scalar(w, 1.0f32.into());
    }
    let w = B::float_reshape(w, Shape::from(w_shape));

    let dyw = B::float_mul(dy.clone(), w);
    let dot = B::float_mean_dim(B::float_mul(dyw.clone(), x.clone()), rank - 1);
    let r3 = B::float_mul(B::float_mul(r.clone(), r.clone()), r.clone());
    let dx = B::float_sub(
        B::float_mul(dyw, r.clone()),
        B::float_mul(x.clone(), B::float_mul(r3, dot)),
    );

    let rows = shape.num_elements() / d;
    let dgamma = B::float_reshape(B::float_mul(B::float_mul(dy, x), r), Shape::new([rows, d]));
    let dgamma = B::float_reshape(B::float_sum_dim(dgamma, 0), Shape::new([d]));

    (B::float_cast(dx, x_dtype), B::float_cast(dgamma, g_dtype))
}

impl<B, C> LlmOps for Autodiff<B, C>
where
    B: Backend + LlmOps,
    C: CheckpointStrategy,
{
    fn quantized_matmul(
        x: FloatTensor<Self>,
        data: IntTensor<Self>,
        scales: FloatTensor<Self>,
        biases: FloatTensor<Self>,
        bits: u32,
        group_size: usize,
        affine: bool,
    ) -> FloatTensor<Self> {
        #[derive(Debug)]
        struct QuantizedMatmulBackward;

        impl<B: Backend + LlmOps> Backward<B, 1> for QuantizedMatmulBackward {
            type State = (IntTensor<B>, FloatTensor<B>, FloatTensor<B>, (u32, usize, bool));

            fn backward(self, ops: Ops<Self::State, 1>, grads: &mut Gradients, _: &mut Checkpointer) {
                let [node_x] = ops.parents;
                let grad = grads.consume::<B>(&ops.node);
                if let Some(node) = node_x {
                    let (data, scales, biases, format) = ops.state;
                    grads.register::<B>(node.id, packed_input_grad::<B>(grad, data, scales, biases, format));
                }
            }
        }

        let scales = scales.into_primitive();
        let biases = biases.into_primitive();
        let format = (bits, group_size, affine);
        match QuantizedMatmulBackward
            .prepare::<C>([x.node()])
            .compute_bound()
            .stateful()
        {
            OpsKind::Tracked(prep) => {
                let y = B::quantized_matmul(
                    x.into_primitive(),
                    data.clone(),
                    scales.clone(),
                    biases.clone(),
                    bits,
                    group_size,
                    affine,
                );
                prep.finish((data, scales, biases, format), y)
            }
            OpsKind::UnTracked(prep) => prep.finish(B::quantized_matmul(
                x.into_primitive(),
                data,
                scales,
                biases,
                bits,
                group_size,
                affine,
            )),
        }
    }

    fn dequantize_packed(
        data: IntTensor<Self>,
        scales: FloatTensor<Self>,
        biases: FloatTensor<Self>,
        bits: u32,
        group_size: usize,
        affine: bool,
    ) -> FloatTensor<Self> {
        // The decoded weight is a constant of the frozen base.
        #[derive(Debug)]
        struct DequantizeBackward;

        impl<B: Backend> Backward<B, 1> for DequantizeBackward {
            type State = ();

            fn backward(self, ops: Ops<Self::State, 1>, grads: &mut Gradients, _: &mut Checkpointer) {
                grads.consume::<B>(&ops.node);
            }
        }

        let prep = DequantizeBackward.prepare::<C>([scales.node()]).compute_bound();
        let w = B::dequantize_packed(
            data,
            scales.into_primitive(),
            biases.into_primitive(),
            bits,
            group_size,
            affine,
        );
        prep.stateless(w)
    }

    fn gather_quantized_matmul(
        x: FloatTensor<Self>,
        data: IntTensor<Self>,
        scales: FloatTensor<Self>,
        biases: FloatTensor<Self>,
        indices: IntTensor<Self>,
        bits: u32,
        group_size: usize,
        affine: bool,
    ) -> FloatTensor<Self> {
        #[derive(Debug)]
        struct GatherQuantizedMatmulBackward;

        impl<B: Backend + LlmOps> Backward<B, 1> for GatherQuantizedMatmulBackward {
            type State = (
                IntTensor<B>,
                FloatTensor<B>,
                FloatTensor<B>,
                IntTensor<B>,
                (u32, usize, bool),
            );

            fn backward(self, ops: Ops<Self::State, 1>, grads: &mut Gradients, _: &mut Checkpointer) {
                let [node_x] = ops.parents;
                let grad = grads.consume::<B>(&ops.node);
                let Some(node) = node_x else { return };
                let (data, scales, biases, indices, (bits, group_size, affine)) = ops.state;

                // dx[t] = dy[t] · W[indices[t]]ᵀ, decoding only the selected
                // experts (one copy per row, as the forward default does).
                let dtype = FloatDType::from(grad.dtype());
                let [t, n] = [grad.shape()[0], grad.shape()[1]];
                let d_shape = data.shape();
                let (k, wpr) = (d_shape[1], d_shape[2]);
                let gpr = scales.shape()[2];
                let data = B::int_reshape(B::int_select(data, 0, indices.clone()), Shape::new([t * k, wpr]));
                let scales =
                    B::float_reshape(B::float_select(scales, 0, indices.clone()), Shape::new([t * k, gpr]));
                let biases = B::float_reshape(B::float_select(biases, 0, indices), Shape::new([t * k, gpr]));
                let w = B::dequantize_packed(data, scales, biases, bits, group_size, affine);
                let w = B::float_reshape(B::float_cast(w, dtype), Shape::new([t, k, n]));
                let dy = B::float_reshape(grad, Shape::new([t, n, 1]));
                let dx = B::float_reshape(B::float_matmul(w, dy), Shape::new([t, k]));
                grads.register::<B>(node.id, dx);
            }
        }

        let scales = scales.into_primitive();
        let biases = biases.into_primitive();
        let format = (bits, group_size, affine);
        match GatherQuantizedMatmulBackward
            .prepare::<C>([x.node()])
            .compute_bound()
            .stateful()
        {
            OpsKind::Tracked(prep) => {
                let y = B::gather_quantized_matmul(
                    x.into_primitive(),
                    data.clone(),
                    scales.clone(),
                    biases.clone(),
                    indices.clone(),
                    bits,
                    group_size,
                    affine,
                );
                prep.finish((data, scales, biases, indices, format), y)
            }
            OpsKind::UnTracked(prep) => prep.finish(B::gather_quantized_matmul(
                x.into_primitive(),
                data,
                scales,
                biases,
                indices,
                bits,
                group_size,
                affine,
            )),
        }
    }

    fn batched_quantized_matmul(
        x: FloatTensor<Self>,
        data: IntTensor<Self>,
        scales: FloatTensor<Self>,
        biases: FloatTensor<Self>,
        rows: usize,
        bits: u32,
        group_size: usize,
        affine: bool,
        transpose: bool,
    ) -> FloatTensor<Self> {
        #[derive(Debug)]
        struct BatchedQuantizedMatmulBackward;

        impl<B: Backend + LlmOps> Backward<B, 1> for BatchedQuantizedMatmulBackward {
            type State = (IntTensor<B>, FloatTensor<B>, FloatTensor<B>, usize, (u32, usize, bool, bool));

            fn backward(self, ops: Ops<Self::State, 1>, grads: &mut Gradients, _: &mut Checkpointer) {
                let [node_x] = ops.parents;
                let grad = grads.consume::<B>(&ops.node);
                let Some(node) = node_x else { return };
                let (data, scales, biases, rows, (bits, group_size, affine, transpose)) = ops.state;
                // y = x·W gives dx = dy·Wᵀ; y = x·Wᵀ gives dx = dy·W.
                let dtype = FloatDType::from(grad.dtype());
                let w = decode_batched::<B>(data, scales, biases, rows, bits, group_size, affine, dtype);
                let w = if transpose { w } else { B::float_transpose(w) };
                grads.register::<B>(node.id, B::float_matmul(grad, w));
            }
        }

        let scales = scales.into_primitive();
        let biases = biases.into_primitive();
        let format = (bits, group_size, affine, transpose);
        match BatchedQuantizedMatmulBackward
            .prepare::<C>([x.node()])
            .compute_bound()
            .stateful()
        {
            OpsKind::Tracked(prep) => {
                let y = B::batched_quantized_matmul(
                    x.into_primitive(),
                    data.clone(),
                    scales.clone(),
                    biases.clone(),
                    rows,
                    bits,
                    group_size,
                    affine,
                    transpose,
                );
                prep.finish((data, scales, biases, rows, format), y)
            }
            OpsKind::UnTracked(prep) => prep.finish(B::batched_quantized_matmul(
                x.into_primitive(),
                data,
                scales,
                biases,
                rows,
                bits,
                group_size,
                affine,
                transpose,
            )),
        }
    }

    fn rms_norm(
        x: FloatTensor<Self>,
        gamma: FloatTensor<Self>,
        eps: f32,
        unit_offset: bool,
    ) -> FloatTensor<Self> {
        #[derive(Debug)]
        struct RmsNormBackward;

        impl<B: Backend> Backward<B, 2> for RmsNormBackward {
            type State = (FloatTensor<B>, FloatTensor<B>, f32, bool);

            fn backward(self, ops: Ops<Self::State, 2>, grads: &mut Gradients, _: &mut Checkpointer) {
                let [node_x, node_gamma] = ops.parents;
                let grad = grads.consume::<B>(&ops.node);
                let (x, gamma, eps, unit_offset) = ops.state;
                let (dx, dgamma) = rms_norm_backward::<B>(x, gamma, grad, eps, unit_offset);
                if let Some(node) = node_x {
                    grads.register::<B>(node.id, dx);
                }
                if let Some(node) = node_gamma {
                    grads.register::<B>(node.id, dgamma);
                }
            }
        }

        match RmsNormBackward
            .prepare::<C>([x.node(), gamma.node()])
            .compute_bound()
            .stateful()
        {
            OpsKind::Tracked(prep) => {
                let (x, gamma) = (x.into_primitive(), gamma.into_primitive());
                let y = B::rms_norm(x.clone(), gamma.clone(), eps, unit_offset);
                prep.finish((x, gamma, eps, unit_offset), y)
            }
            OpsKind::UnTracked(prep) => prep.finish(B::rms_norm(
                x.into_primitive(),
                gamma.into_primitive(),
                eps,
                unit_offset,
            )),
        }
    }

    fn rope(
        x: FloatTensor<Self>,
        inv_freq: FloatTensor<Self>,
        offset: usize,
        traditional: bool,
    ) -> FloatTensor<Self> {
        // RoPE is an orthogonal rotation of each pair, so its transpose is the
        // rotation by the opposite angle: rope with `-inv_freq`. The schedule
        // itself is a constant.
        #[derive(Debug)]
        struct RopeBackward;

        impl<B: Backend + LlmOps> Backward<B, 1> for RopeBackward {
            type State = (FloatTensor<B>, usize, bool);

            fn backward(self, ops: Ops<Self::State, 1>, grads: &mut Gradients, _: &mut Checkpointer) {
                let [node_x] = ops.parents;
                let grad = grads.consume::<B>(&ops.node);
                if let Some(node) = node_x {
                    let (inv_freq, offset, traditional) = ops.state;
                    let dx = B::rope(grad, B::float_neg(inv_freq), offset, traditional);
                    grads.register::<B>(node.id, dx);
                }
            }
        }

        let inv_freq = inv_freq.into_primitive();
        match RopeBackward.prepare::<C>([x.node()]).compute_bound().stateful() {
            OpsKind::Tracked(prep) => {
                let y = B::rope(x.into_primitive(), inv_freq.clone(), offset, traditional);
                prep.finish((inv_freq, offset, traditional), y)
            }
            OpsKind::UnTracked(prep) => {
                prep.finish(B::rope(x.into_primitive(), inv_freq, offset, traditional))
            }
        }
    }
}
